#!/usr/bin/env python3
"""Patch the IP-packaged xfft core wrapper generated by hls::fft.

The Vitis HLS 2024.2 RTL backend connects m_axis_data_tready and the
status/data-out halt events on the core instance, but the packaged VHDL
core wrapper (the "viv" wrapper) does not expose them.  Add the ports and
wire them to the internal xfft core (which has all three).
"""
import glob
import os
import re
import sys

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "hw", "ip_repo", "wiener_stream", "hdl", "ip")
def patch_fft_core_ce(root: str) -> int:
    """Keep ap_ce high while fft_core waits for the hls::fft wrapper ap_done."""
    n = 0
    for path in glob.glob(os.path.join(root, "hdl", "verilog", "wiener_stream_fft_core.v")):
        s = open(path).read()
        old = "if (((1'b1 == ap_CS_fsm_state4) | (1'b1 == ap_CS_fsm_state3))) begin\n        grp_fft_fft_cfg_s_fu_83_ap_ce = 1'b1;"
        new = "if (((1'b1 == ap_CS_fsm_state5) | (1'b1 == ap_CS_fsm_state4) | (1'b1 == ap_CS_fsm_state3))) begin\n        grp_fft_fft_cfg_s_fu_83_ap_ce = 1'b1;"
        if old in s:
            open(path, "w").write(s.replace(old, new))
            n += 1
            print("ap_ce patched", path)
    return n

patched = 0
for path in glob.glob(os.path.join(ROOT, "*_core_ip.vhd")):
    s = open(path).read()
    if "m_axis_data_tready => m_axis_data_tready" in s:
        continue
    # 1) add ports to the entity
    s = s.replace(
        "    m_axis_data_tlast : OUT STD_LOGIC;\n    event_frame_started : OUT STD_LOGIC;",
        "    m_axis_data_tlast : OUT STD_LOGIC;\n"
        "    m_axis_data_tready : IN STD_LOGIC;\n"
        "    event_frame_started : OUT STD_LOGIC;",
    )
    s = s.replace(
        "    event_data_in_channel_halt : OUT STD_LOGIC\n  );",
        "    event_data_in_channel_halt : OUT STD_LOGIC;\n"
        "    event_status_channel_halt : OUT STD_LOGIC;\n"
        "    event_data_out_channel_halt : OUT STD_LOGIC\n  );",
    )
    # 2) wire them to the internal core
    s = s.replace("      m_axis_data_tready => '1',", "      m_axis_data_tready => m_axis_data_tready,")
    s = s.replace(
        "      event_data_in_channel_halt => event_data_in_channel_halt\n    );",
        "      event_data_in_channel_halt => event_data_in_channel_halt,\n"
        "      event_status_channel_halt => event_status_channel_halt,\n"
        "      event_data_out_channel_halt => event_data_out_channel_halt\n    );",
    )
    open(path, "w").write(s)
    patched += 1
    print("patched", path)
print("patched files:", patched)
print("ap_ce patched:", patch_fft_core_ce(os.path.join(ROOT, "..")))
